      "label": "A",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "赤脚踏进正午海 白亮晃眼的光"
        },
        {
          "id": "V1-02",
          "zh": "我喊你名字的时候 脚背被浪打湿"
        },
        {
          "id": "V1-03",
          "zh": "忘了潮水忘了风 皮肤结成薄盐"
        },
